toad_implementation.code_blueprint:
canvas {
  size: 800px 900px;
  fill: #18110B;
  font-family: "Almendra, serif";
}

>pitchBlack = #18110B;
>torchGlow = #E65100;
>oldGold = #B8860B;
>parchment = #D2B48C;
>ironGray = #3E3835;

circle #fireGlow {
  at: center of canvas offset 0px -60px;
  size: 420px;
  fill: alpha(>torchGlow, 0.35);
}

rect #signBoard {
  at: center of canvas;
  size: 620px 720px;
  fill: #221812;
  stroke: >oldGold;
  stroke-width: 4px;
  radius: 12px;
}

circle #ironRivetTL {
  at: top left of #signBoard offset 20px 20px;
  size: 16px;
  fill: >ironGray;
}

circle #ironRivetTR {
  at: top right of #signBoard offset -20px 20px;
  size: 16px;
  fill: >ironGray;
}

text #marketTitle {
  at: top center of #signBoard offset 0px 56px;
  content: "MITTELALTER-SPEKTAKEL";
  font-size: 34px;
  font-weight: 700;
  color: >torchGlow;
}

text #marketSubtitle {
  at: below #marketTitle offset 16px;
  content: "ZU RUNENSTEIN • ANNO DOMINI 2026";
  font-size: 16px;
  color: >parchment;
}

rect #heraldicShield {
  at: below #marketSubtitle offset 40px;
  size: 160px 200px;
  fill: #7F1D1D;
  stroke: >oldGold;
  stroke-width: 4px;
  radius: 0px 0px 80px 80px;
}

text #shieldEmblem {
  at: center of #heraldicShield;
  content: "⚔";
  font-size: 64px;
  color: >oldGold;
}

text #calloutText {
  at: below #heraldicShield offset 50px;
  content: "GAUKLER • RITTERKAMPF • TAVERNEY";
  font-size: 15px;
  font-weight: 700;
  color: >oldGold;
}
